"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[5808],{3427(e,n,r){r.d(n,{content:()=>h,description:()=>t,keywords:()=>a,title:()=>s});r(5043);var i=r(579);const s="KI-Erkennung funktioniert nicht. Prozessbasierte Bewertung schon.",t="82% der P\xe4dagogen bef\xfcrchten KI-Betrug, doch Erkennungstools versagen. Prozessbasierte praktische Bewertung bietet einen besseren Weg.",a=["KI Bewertung","formative Bewertung KI","KI-Erkennung Bildung","Pearson Bewertungsforschung","virtuelles Labor Benotung","prozessbasierte Bewertung","KI-resistente Bewertung","naturwissenschaftliche Bildung KI","praktische Bewertung","Lehrer KI Benotung"],h=(0,i.jsxs)("div",{children:[(0,i.jsxs)("figure",{className:"blog-image",children:[(0,i.jsx)("img",{src:"/images/potato.jpg",alt:"Sch\xfcler f\xfchrt praktische Bewertung im virtuellen Labor durch, in diesem Beispiel schneidet der Sch\xfcler eine Kartoffel f\xfcr mikrobiologische Experimente",style:{width:"100%",maxWidth:"700px",margin:"0 auto 1.5rem",display:"block",borderRadius:"8px"}}),(0,i.jsx)("figcaption",{style:{textAlign:"center",fontStyle:"italic",color:"#666",marginBottom:"1.5rem"},children:"Prozessbasierte Bewertung erfasst, was Sch\xfcler tats\xe4chlich tun, nicht nur was sie abgeben"})]}),(0,i.jsxs)("p",{children:["Im Dezember 2025 ver\xf6ffentlichte Pearson eine Erkenntnis, die niemanden im Bildungswesen \xfcberraschte: ",(0,i.jsx)("a",{href:"https://plc.pearson.com/en-GB/news-and-insights/assessment-evolved-redefining-formative-assessment-in-a-generative-ai-era",target:"_blank",rel:"noopener noreferrer",children:"82% der P\xe4dagogen sind besorgt dar\xfcber, dass Sch\xfcler GenAI zur Erledigung von Aufgaben nutzen"}),". Die institutionelle Reaktion war vorhersehbar: Erkennungstools, \xdcberwachungssoftware und Richtlinien, die KI als etwas behandeln, das man erwischen und bestrafen muss."]}),(0,i.jsx)("p",{children:"Zwei Jahre nach der weitverbreiteten ChatGPT-Nutzung k\xf6nnen wir sehen, wie gut das funktioniert. Erkennungstools produzieren falsch-positive Ergebnisse, die das Vertrauen zu Sch\xfclern zerst\xf6ren. Richtlinien unterscheiden sich drastisch zwischen Abteilungen, geschweige denn zwischen Institutionen. Sch\xfcler, die KI weit h\xe4ufiger nutzen als P\xe4dagogen sch\xe4tzen, sind einfach besser darin geworden, es zu verbergen."}),(0,i.jsx)("p",{children:"Pearsons Forschung weist jedoch auf etwas Grundlegenderes hin. Das Risiko ist nicht wirklich Betrug. Das Risiko besteht darin, dass Sch\xfcler die kognitive Arbeit \xfcberspringen, die das Lernen \xfcberhaupt erst erm\xf6glicht. Wenn ein Sch\xfcler ChatGPT seinen Laborbericht schreiben l\xe4sst, hat er nicht nur bei einer Aufgabe betrogen. Er hat das Denken verpasst, das die Aufgabe hervorbringen sollte."}),(0,i.jsx)("p",{children:"Bei WhimsyLabs sind wir anders an dieses Problem herangegangen. Anstatt zu fragen, wie man KI-Nutzung erkennt, haben wir gefragt, wie man Bewertungen gestaltet, bei denen KI einfach nicht helfen kann."}),(0,i.jsx)("h2",{children:"Warum Erkennung scheitert"}),(0,i.jsx)("p",{children:"KI-Erkennungstools behaupten, maschinell generierten Text mit hoher Genauigkeit zu identifizieren. Die Realit\xe4t ist chaotischer. Diese Tools haben Schwierigkeiten, KI-Schreiben von menschlichem Schreiben zu unterscheiden, besonders wenn Sch\xfcler beim Prompting versierter werden. Sie produzieren auch falsch-positive Ergebnisse und kennzeichnen manchmal Arbeiten, die Sch\xfcler tats\xe4chlich selbst geschrieben haben. F\xfcr einen Sch\xfcler, der f\xe4lschlicherweise des KI-Betrugs beschuldigt wird, kann der Schaden an seiner Beziehung zur Institution dauerhaft sein."}),(0,i.jsx)("p",{children:'Kane Murdoch, der an der Macquarie University f\xfcr Beschwerden und Fehlverhalten zust\xe4ndig ist, formuliert es in Pearsons Bericht treffend: \u201eDas Problem mit Detektoren ist, dass sie keine Beweise generieren... Sobald jemand diese Zahl sieht, die der Detektor liefert, wird er w\xe4hrend jedes nachfolgenden Prozesses voreingenommen sein."'}),(0,i.jsx)("p",{children:"\xdcber die Genauigkeitsprobleme hinaus schafft Erkennung eine adversative Dynamik. Sie nimmt an, dass Sch\xfcler betr\xfcgen, bis das Gegenteil bewiesen ist. Sie verbraucht Zeit und Energie, die in tats\xe4chlichen Unterricht flie\xdfen k\xf6nnten. Und sie tut nichts, um das grundlegende Problem anzugehen, ob Sch\xfcler tats\xe4chlich lernen."}),(0,i.jsx)("h2",{children:"Prozess statt Produkt bewerten"}),(0,i.jsx)("p",{children:"Erw\xe4gen Sie, zu bewerten, wie Sch\xfcler arbeiten, anstatt nur was sie produzieren."}),(0,i.jsx)("p",{children:"Dies ist der Ansatz, den wir in WhimsyLabs eingebaut haben. Unsere virtuellen Labore lassen Sch\xfcler nicht nur Experimente durchf\xfchren. Sie erfassen detaillierte Daten \xfcber jede Aktion: wie pr\xe4zise Sch\xfcler pipettieren, ob sie Endpunkte korrekt erkennen, wie sie mit Ger\xe4ten umgehen, ob sie Sicherheitsprotokolle befolgen."}),(0,i.jsx)("p",{children:"Diese Daten erm\xf6glichen etwas, was traditionelle Bewertung nicht kann: prozedurale Kompetenz direkt zu evaluieren. Wir fragen Sch\xfcler nicht, zu beschreiben, wie sie eine Titration durchf\xfchren w\xfcrden. Wir beobachten sie dabei. Wir messen ihre Pr\xe4zision. Wir sehen, ob sie Luftblasen aus der B\xfcrette entfernen. Wir wissen, ob sie den Endpunkt \xfcberschreiten."}),(0,i.jsx)("p",{children:"ChatGPT kann keine virtuelle Titration f\xfcr einen Sch\xfcler durchf\xfchren. Es gibt nichts zu erkennen, weil es nichts zu f\xe4lschen gibt."}),(0,i.jsx)("h2",{children:"Was wir messen"}),(0,i.jsx)("p",{children:"Wenn ein Sch\xfcler ein virtuelles Experiment abschlie\xdft, erfassen wir nicht nur sein Endergebnis. Wir sammeln Beweise \xfcber mehrere Dimensionen:"}),(0,i.jsxs)("ul",{children:[(0,i.jsxs)("li",{children:[(0,i.jsx)("strong",{children:"Pr\xe4zision:"})," Waren Messungen \xfcber Versuche hinweg konsistent? (\xb10,02 mL oder \xb10,5 mL?)"]}),(0,i.jsxs)("li",{children:[(0,i.jsx)("strong",{children:"Technik:"})," Sanfte Hahnkontrolle? Korrektes Schwenken des Kolbens?"]}),(0,i.jsxs)("li",{children:[(0,i.jsx)("strong",{children:"Timing:"})," Wie schnell haben sie den Endpunkt erkannt? Wie lange dauerte der Aufbau?"]}),(0,i.jsxs)("li",{children:[(0,i.jsx)("strong",{children:"Sicherheit:"})," Richtige PSA? Korrekter Umgang mit Chemikalien und Entsorgung?"]}),(0,i.jsxs)("li",{children:[(0,i.jsx)("strong",{children:"Probleml\xf6sung:"})," Wie haben sie reagiert, als Ergebnisse unerwartet waren?"]})]}),(0,i.jsx)("p",{children:'Pearson nennt dies \u201ereichhaltigere Formen von Beweisen". Traditionelle Bewertungen k\xf6nnen diese Art von Daten einfach nicht erfassen. Noch wichtiger f\xfcr das KI-Problem: Diese Beweise erfordern, dass der Sch\xfcler die Arbeit tats\xe4chlich durchgef\xfchrt hat.'}),(0,i.jsx)("h2",{children:"KI, die Lehrern hilft, nicht Sch\xfclern beim Betr\xfcgen"}),(0,i.jsx)("p",{children:"Unsere L\xf6sung f\xfcr das KI-Bewertungsproblem beinhaltet tats\xe4chlich KI, aber in einer anderen Rolle. Anstatt Sch\xfclern zu helfen, das Lernen zu \xfcberspringen, nutzen wir KI, um Lehrern bei der Bewertung des Lernens zu helfen."}),(0,i.jsx)("p",{children:"Wenn ein Sch\xfcler ein virtuelles Experiment abschlie\xdft, analysiert unser System sein Aktionsprotokoll und experimentelle Daten. Es schl\xe4gt Noten \xfcber f\xfcnf Dimensionen vor: experimentelles Verfahren, Datenerfassung, Berechnungen, Laborsicherheit und wissenschaftliche Kommunikation. Jeder Vorschlag enth\xe4lt ein Konfidenzniveau (75-98%), das Lehrern zeigt, wo KI-Bewertung zuverl\xe4ssig ist und wo menschliches Urteil wichtiger ist. Lehrer \xfcberpr\xfcfen, passen an und genehmigen Endnoten. Die KI \xfcbernimmt die zeitaufw\xe4ndige Analyse. Der Mensch trifft die Ermessensentscheidungen."}),(0,i.jsx)("p",{children:'Dies entspricht dem, was Pearsons Expertengremium empfiehlt: KI als \u201eKraftverst\xe4rker f\xfcr formative Bewertung" zu nutzen, w\xe4hrend sichergestellt wird, dass P\xe4dagogen die Kontrolle behalten.'}),(0,i.jsx)("h2",{children:"Warum praktische Bewertung KI-Abk\xfcrzungen widersteht"}),(0,i.jsx)("p",{children:"Pearsons Forschung fragte P\xe4dagogen, welche Bewertungstypen am anf\xe4lligsten f\xfcr KI-Missbrauch waren. Die Ergebnisse waren nicht \xfcberraschend. Essays, Programmieraufgaben und Multiple-Choice-Fragen rangierten als am anf\xe4lligsten. Simulationen und spielbasierte Aktivit\xe4ten rangierten als am wenigsten anf\xe4llig."}),(0,i.jsx)("p",{children:"Das macht Sinn. Man kann ChatGPT auffordern, \xfcber Chemie zu schreiben. Man kann es nicht auffordern, Chemie zu machen. Die physische Natur praktischer Arbeit schafft eine Barriere, die textbasierte KI nicht \xfcberwinden kann."}),(0,i.jsx)("p",{children:"F\xfcr den naturwissenschaftlichen Unterricht sind das eigentlich gute Nachrichten. Die F\xe4cher, die praktische Arbeit erfordern, sind genau die F\xe4cher, bei denen KI-Abk\xfcrzungen versagen. Wir m\xfcssen nicht gegen die Technologie k\xe4mpfen. Wir m\xfcssen das betonen, was naturwissenschaftliche Bildung vom Aufsatzschreiben unterscheidet."}),(0,i.jsx)("div",{className:"bluesky-embed-container",style:{margin:"20px 0",textAlign:"center"},children:(0,i.jsx)("bsky-embed",{search:"Looking through the microscope in our VR science lab!",limit:"1","link-target":"_blank","custom-styles":".border-slate-300 { border-color: #e1e8ed; border-radius: 12px; max-width: 600px; margin: 0 auto; }"})}),(0,i.jsx)("h2",{children:"Das eigentliche Problem"}),(0,i.jsx)("p",{children:"Amanda Bickerstaff, CEO von AI for Education, identifiziert die Kernbedenken in Pearsons Bericht:"}),(0,i.jsx)("blockquote",{style:{borderLeft:"4px solid #dabeff",paddingLeft:"1rem",margin:"1.5rem 0",fontStyle:"italic"},children:'\u201eDer tiefere Grund, warum akademische Integrit\xe4tsverletzungen gerade so be\xe4ngstigend sind, ist die Bef\xfcrchtung, dass Kinder beginnen werden, die Rolle der Bildung, die Rolle des Lernens abzuwerten."'}),(0,i.jsx)("p",{children:"Erkennung und Bestrafung werden das nicht beheben. Zu demonstrieren, dass Bildung immer noch wichtig ist, schon. Und der Weg dahin f\xfchrt \xfcber die Bewertung von Dingen, die tats\xe4chlich Lernen erfordern, um sie zu demonstrieren."}),(0,i.jsx)("p",{children:"Wenn wir Sch\xfcler nach ihrer F\xe4higkeit bewerten, eine Titration physisch mit Pr\xe4zision durchzuf\xfchren, gibt es keine Abk\xfcrzung. Wenn wir sie danach benoten, wie sie mit unerwarteten Ergebnissen w\xe4hrend eines Experiments umgehen, kann KI nicht helfen. Wenn wir ihre Technik, ihr Timing und ihre Sicherheitseinhaltung in Echtzeit evaluieren, wird die Bewertung untrennbar vom Lernen."}),(0,i.jsx)("h2",{children:"Der Weg nach vorn"}),(0,i.jsx)("p",{children:"Wir glauben, dass die L\xf6sung f\xfcr das KI-Bewertungsproblem nicht mehr \xdcberwachung oder strengere Richtlinien ist. Es ist besseres Bewertungsdesign. Bewertungen, die authentische Demonstration von F\xe4higkeiten erfordern, reichhaltige Beweise des Lernens erfassen und KI nutzen, um menschliches Urteil zu verst\xe4rken, anstatt es zu ersetzen."}),(0,i.jsx)("p",{children:"Das bedeutet nicht, schriftliche Bewertungen aufzugeben. Aber es bedeutet, ihre Grenzen anzuerkennen und sie mit Methoden zu erg\xe4nzen, die erfassen, was Schreiben nicht kann: prozedurales Wissen, Technik, die F\xe4higkeit, unter Druck zu arbeiten und sich anzupassen, wenn etwas schiefgeht."}),(0,i.jsx)("p",{children:"Bei WhimsyLabs bauen wir Werkzeuge, um das m\xf6glich zu machen. Denn die Zukunft der Bewertung geht nicht darum, Betr\xfcger zu erwischen. Es geht darum, Lernerfahrungen zu gestalten, die es wert sind, ehrlich gemacht zu werden."}),(0,i.jsxs)("p",{children:["Interessiert daran, dies in Aktion zu sehen? ",(0,i.jsx)("a",{href:"/contact",children:"Kontaktieren Sie uns"}),", um zu erfahren, wie WhimsyLabs die praktische naturwissenschaftliche Bewertung an Ihrer Schule verbessern kann."]}),(0,i.jsx)("hr",{style:{margin:"2rem 0",border:"none",borderTop:"1px solid #ddd"}}),(0,i.jsx)("p",{style:{fontSize:"0.9rem",color:"#666"},children:(0,i.jsx)("strong",{children:"Quellen:"})}),(0,i.jsxs)("ul",{style:{fontSize:"0.9rem",color:"#666"},children:[(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"https://plc.pearson.com/en-GB/news-and-insights/assessment-evolved-redefining-formative-assessment-in-a-generative-ai-era",target:"_blank",rel:"noopener noreferrer",children:"Pearson (2025). Assessment Evolved: Redefining Formative Assessment in a Generative AI Era."})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"https://arxiv.org/abs/2303.11156",target:"_blank",rel:"noopener noreferrer",children:"Liang, W. et al. (2023). GPT detectors are biased against non-native English writers. arXiv."})})]})]})}}]);
